"use client"

import { useState, useRef } from "react"
import { Card, CardContent } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { ChevronLeft, ChevronRight, Star, Bookmark } from "lucide-react"

const featuredPlaces = [
  {
    id: 1,
    name: "Santorini, Greece",
    description: "Iconic white-washed buildings with stunning sunsets",
    image: "/santorini-sunset.png",
    rating: 4.9,
    category: "Island",
  },
  {
    id: 2,
    name: "Kyoto, Japan",
    description: "Ancient temples and traditional gardens",
    image: "/kyoto-japan-temple-autumn-leaves.jpg",
    rating: 4.8,
    category: "Cultural",
  },
  {
    id: 3,
    name: "Machu Picchu, Peru",
    description: "Ancient Incan citadel in the Andes Mountains",
    image: "/machu-picchu-ruins.png",
    rating: 4.9,
    category: "Historical",
  },
  {
    id: 4,
    name: "Bali, Indonesia",
    description: "Tropical paradise with rice terraces and beaches",
    image: "/bali-indonesia-rice-terraces-green-tropical.jpg",
    rating: 4.7,
    category: "Tropical",
  },
  {
    id: 5,
    name: "Iceland Northern Lights",
    description: "Witness the magical aurora borealis",
    image: "/iceland-northern-lights-aurora-borealis-night-sky.jpg",
    rating: 4.9,
    category: "Nature",
  },
  {
    id: 6,
    name: "Swiss Alps",
    description: "Majestic mountain peaks and scenic villages",
    image: "/swiss-alps-mountains-village-scenic-winter.jpg",
    rating: 4.8,
    category: "Mountains",
  },
]

export function FeaturedPlaces() {
  const scrollContainerRef = useRef<HTMLDivElement>(null)
  const [bookmarked, setBookmarked] = useState<number[]>([])

  const scroll = (direction: "left" | "right") => {
    if (scrollContainerRef.current) {
      const scrollAmount = 340
      scrollContainerRef.current.scrollBy({
        left: direction === "left" ? -scrollAmount : scrollAmount,
        behavior: "smooth",
      })
    }
  }

  const toggleBookmark = (id: number) => {
    setBookmarked((prev) => (prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]))
  }

  return (
    <section className="py-16 bg-secondary/30">
      <div className="container mx-auto px-4">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h2 className="text-3xl font-bold mb-2">Featured Destinations</h2>
            <p className="text-muted-foreground">Handpicked places loved by travelers</p>
          </div>
          <div className="hidden sm:flex gap-2">
            <Button variant="outline" size="icon" onClick={() => scroll("left")}>
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <Button variant="outline" size="icon" onClick={() => scroll("right")}>
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>

        <div
          ref={scrollContainerRef}
          className="flex gap-4 overflow-x-auto pb-4 snap-x snap-mandatory scrollbar-hide"
          style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}
        >
          {featuredPlaces.map((place) => (
            <Card key={place.id} className="flex-shrink-0 w-[300px] snap-start overflow-hidden group cursor-pointer">
              <div className="relative h-48 overflow-hidden">
                <img
                  src={place.image || "/placeholder.svg"}
                  alt={place.name}
                  className="w-full h-full object-cover transition-transform group-hover:scale-105"
                />
                <Button
                  variant="ghost"
                  size="icon"
                  className="absolute top-2 right-2 bg-background/80 backdrop-blur-sm hover:bg-background"
                  onClick={(e) => {
                    e.stopPropagation()
                    toggleBookmark(place.id)
                  }}
                >
                  <Bookmark className={`h-4 w-4 ${bookmarked.includes(place.id) ? "fill-primary text-primary" : ""}`} />
                </Button>
                <Badge className="absolute bottom-2 left-2" variant="secondary">
                  {place.category}
                </Badge>
              </div>
              <CardContent className="p-4">
                <div className="flex items-start justify-between mb-2">
                  <h3 className="font-semibold">{place.name}</h3>
                  <div className="flex items-center gap-1 text-sm">
                    <Star className="h-4 w-4 fill-accent text-accent" />
                    <span>{place.rating}</span>
                  </div>
                </div>
                <p className="text-sm text-muted-foreground line-clamp-2">{place.description}</p>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    </section>
  )
}
